def f(g):
    g=[r[:] for r in g]; h,w=len(g),len(g[0])
    C=Counter(x for r in g for x in r)
    bg=C.most_common(1)[0][0]
    mi=[c for c in C if c!=bg][0]
    fullrows={i for i in range(h) if all(x==mi for x in g[i])}
    fullcols={j for j in range(w) if all(g[i][j]==mi for i in range(h))}
